// registry.js - the module scope is the singleton the classic pattern needed.
const services = new Map();
export const register = (token, factory) => services.set(token, factory);
export const resolve = (token) => {
  const factory = services.get(token);
  if (!factory) throw new Error(`unregistered service: ${String(token)}`);
  return factory();
};

